css:
/* Post: the AI4Dealerships announcement.

   The Blog post template already draws everything this handoff's chrome asks for
   — back link, category pill, date and read time, H1, subtitle, byline avatar,
   940px cover, 720px reading column, related cards, header and footer. What is
   left here is the three shapes that are this post's own: an uncropped promo
   cover, the yellow "charge" callout, and the dark CTA box. Every selector is
   scoped to this post's own nodes. */

/* Cover: a 1200x627 promo graphic with its headline baked into the pixels, so it
   is shown whole instead of cropped to the template's 460px band. */
main > article > .bz-block:not([data-bz-node]) > .bz-container img { max-height: none; }
main > article > [data-bz-node="hero-image"] img { max-height: none; }

/* The four services read as one bold-led line each, as the handoff draws them. */
main > article .bz-block--list[data-bz-node="does-list"] .bz-feature__t { display: inline; }
main > article .bz-block--list[data-bz-node="does-list"] .bz-feature__t::after { content: ':\00a0'; }
main > article .bz-block--list[data-bz-node="does-list"] .bz-feature__d { display: inline; }

/* Callout: the yellow tint band. --volt is the brand's charge yellow, declared
   site-wide in Design -> Custom code; it has no slot in the token set. */
main > article [data-bz-node="callout-box"] {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  column-gap: 14px;
  align-items: start;
  background: color-mix(in srgb, var(--volt) 34%, var(--card));
  border-radius: 18px;
  padding: 22px 24px;
}
main > article [data-bz-node="callout-box"]::before {
  content: '\26A1';
  grid-row: 1 / span 2;
  font-size: 20px;
  line-height: 1.35;
}
main > article [data-bz-node="callout-t"] h3 {
  font: 800 16.5px/1.4 var(--font-body);
  letter-spacing: 0;
  color: var(--ink);
  margin: 0;
}
main > article [data-bz-node="callout-p"] p { font-size: 16px; line-height: 1.6; margin: 6px 0 0; }

/* CTA box: ink card, blue glow, the charge-yellow button. The background and the
   inner padding are the column's own Appearance settings, so they stay editable;
   only the radius, the glow and the type are written here. */
main > article [data-bz-node="ctabox-card"] {
  position: relative;
  overflow: hidden;
  border-radius: 24px;
}
main > article [data-bz-node="ctabox-card"]::before {
  content: '';
  position: absolute;
  top: -50px;
  right: -20px;
  width: 260px;
  height: 200px;
  background: radial-gradient(circle, color-mix(in srgb, var(--accent) 40%, transparent), transparent 70%);
  pointer-events: none;
}
main > article [data-bz-node="ctabox-card"] > * { position: relative; }
main > article [data-bz-node="ctabox-h"] h3 {
  font: 800 28px/1.1 var(--font-heading);
  letter-spacing: -0.01em;
  color: #fff;
  margin: 0;
}
main > article [data-bz-node="ctabox-p"] p {
  font: 500 16px/1.6 var(--font-body);
  color: color-mix(in srgb, #fff 74%, var(--ink));
  max-width: 560px;
  margin: 12px 0 0;
}
main > article .bz-block--buttons[data-bz-node="ctabox-btns"] .bz-btns { margin: 22px 0 0; }
main > article .bz-block--buttons[data-bz-node="ctabox-btns"] .bz-btn {
  background: var(--volt);
  color: var(--ink);
  font: 700 15.5px/1.2 var(--font-body);
  padding: 14px 26px;
  box-shadow: none;
}
main > article .bz-block--buttons[data-bz-node="ctabox-btns"] .bz-btn:hover { background: color-mix(in srgb, var(--volt) 88%, var(--ink)); }

@media (max-width: 600px) {
  main > article [data-bz-node="ctabox-card"] { padding: 28px 24px; }
  main > article [data-bz-node="ctabox-h"] h3 { font-size: 24px; }
  main > article .bz-block--buttons[data-bz-node="ctabox-btns"] .bz-btn { display: block; width: 100%; }
}
